customMethods.script:
userId = self.view.custom.security.userId
dashboard = dict(self.view.custom.dashboardInfo.dashboard)
if dashboard['roles']: dashboard['roles'] = system.util.jsonEncode(dashboard['roles'])

if dashboard['dashboardId'] is None:
	self.view.params.dashboardId, msg = system.kanoa.dashboard.addDashboard(dashboard, userId)
else:
	retVal, msg = system.kanoa.dashboard.updateDashboard(dashboard, userId)
	self.view.refreshBinding("custom.dashboardInfo")

if msg:	system.perspective.sendMessage('showFailerToast', msg)
else: system.perspective.sendMessage('showSuccessfulToast', 'Dashboard has been saved')

self.view.refreshBinding("custom.dashboards")

return
